export const PERMISSIONS: readonly PermissionMeta[] = Object.freeze(_PERMISSIONS_DATA);

/** Lookup map keyed by permission ID. O(1) check. */
export const PERMISSIONS_BY_ID: ReadonlyMap<string, PermissionMeta> = new Map(
  PERMISSIONS.map((p) => [p.id, p]),
);

/**
 * Permission ID. Intentionally `string` rather than a literal union of
 * the ~1056 catalog entries — TypeScript can't represent that union
 * (TS2590 "too complex"), and even if it could the IntelliSense cost
 * would be prohibitive on consumers. Use PERMISSIONS_BY_ID.has(id) at
 * runtime to validate; the CI drift guard catches typos in seed data.
 */
export type PermissionId = string;

/**
 * Always-permitted core tools. The resolver short-circuits to ALLOW for
 * these regardless of group membership, account override, or agent_policies.
 * Mirrors the bypass list in apps/mcp-server/src/lib/register-tool.ts.
 */
export const ALWAYS_PERMITTED: ReadonlySet<string> = new Set([
  "platform.system.get_info",
  "platform.user.get_profile",
  "agent.self.heartbeat",
]);

/**
 * MCP tool name → catalog permission ID. Generated from the manifest
 * at codegen time so the MCP register-tool wrapper can look up a
 * permission for a tool name without re-deriving the inference.
 * Tools that source from REST routes (no tool name) are absent.
 */
